  "implementation": "def solve(case):
    payload = case['payload']
    edges = payload['edges']
    communities = payload['communities']
    resolution = payload['resolution']
    deg = {}
    for u, v, w in edges:
        deg[u] = deg.get(u, 0) + w
        deg[v] = deg.get(v, 0) + w
    m = sum(w for _, _, w in edges)
    internal = {}
    for u, v, w in edges:
        if communities[u] == communities[v]:
            internal[communities[u]] = internal.get(communities[u], 0) + w
    comm_deg = {}
    for v, c in communities.items():
        k = deg.get(v, 0)
        comm_deg[c] = comm_deg.get(c, 0) + k
    sum_internal = sum(internal.values())
    sum_K2 = sum(k * k for k in comm_deg.values())
    gamma = resolution
    Q = (1.0 / m) * sum_internal - (gamma / (4.0 * m * m)) * sum_K2
    return Q"
